// Service worker: cache-first app shell (fully offline after first load),
// runtime cache for map tiles the user has viewed, network-only for geocoding.
// The PRECACHE list is generated by `node tools/gen-precache.mjs` (a test checks it is complete).
const VERSION = 'aiec-v1-phase7-1';
const SHELL = `shell-${VERSION}`;
const TILES = 'tiles-v1';
const MAX_TILES = 1500;

// PRECACHE:START
const PRECACHE = [
  './',
  './index.html',
  './offline.html',
  './manifest.webmanifest',
  './css/base.css',
  './css/components.css',
  './css/tokens.css',
  './js/aicheck.js',
  './js/api.js',
  './js/app.js',
  './js/camera.js',
  './js/cctv.js',
  './js/chat.js',
  './js/db.js',
  './js/docs.js',
  './js/drawing.js',
  './js/duty.js',
  './js/feedback.js',
  './js/geo.js',
  './js/hex.js',
  './js/i18n.js',
  './js/icons.js',
  './js/lang/en.js',
  './js/lang/hi.js',
  './js/lang/mr.js',
  './js/ledger.js',
  './js/map.js',
  './js/notify.js',
  './js/ocr.js',
  './js/payments.js',
  './js/pdf.js',
  './js/permissions.js',
  './js/prefs.js',
  './js/pricing.js',
  './js/qc.js',
  './js/qr.js',
  './js/screens/amc.js',
  './js/screens/audit.js',
  './js/screens/chats.js',
  './js/screens/common.js',
  './js/screens/help.js',
  './js/screens/home.js',
  './js/screens/install.js',
  './js/screens/login.js',
  './js/screens/mapview.js',
  './js/screens/money.js',
  './js/screens/project.js',
  './js/screens/reports.js',
  './js/screens/rider/capture.js',
  './js/screens/rider/map.js',
  './js/screens/rider/today.js',
  './js/screens/sales/desk.js',
  './js/screens/sales/panel.js',
  './js/screens/settings.js',
  './js/screens/stages/agreement.js',
  './js/screens/stages/closeout.js',
  './js/screens/stages/container.js',
  './js/screens/stages/drawings.js',
  './js/screens/stages/emi.js',
  './js/screens/stages/index.js',
  './js/screens/stages/install.js',
  './js/screens/stages/permit.js',
  './js/screens/stages/qcclear.js',
  './js/screens/stages/readiness.js',
  './js/screens/stages/supply.js',
  './js/seed.js',
  './js/sop.js',
  './js/stages.js',
  './js/supply.js',
  './js/theme.js',
  './js/trust.js',
  './js/ui.js',
  './js/voice.js',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './icons/logo.svg',
  './icons/maskable.svg',
  './vendor/fonts/noto-sans-devanagari-devanagari-400-normal.woff2',
  './vendor/fonts/noto-sans-devanagari-devanagari-700-normal.woff2',
  './vendor/jspdf/jspdf.umd.min.js',
  './vendor/leaflet/images/layers-2x.png',
  './vendor/leaflet/images/layers.png',
  './vendor/leaflet/images/marker-icon-2x.png',
  './vendor/leaflet/images/marker-icon.png',
  './vendor/leaflet/images/marker-shadow.png',
  './vendor/leaflet/leaflet.css',
  './vendor/leaflet/leaflet.js',
  './vendor/qrcode/qrcode.js',
];
const LAZY = [
  './vendor/tesseract/lang/eng.traineddata.gz',
  './vendor/tesseract/tesseract-core-lstm.wasm.js',
  './vendor/tesseract/tesseract.min.js',
  './vendor/tesseract/worker.min.js',
];
// PRECACHE:END

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('shell-') && k !== SHELL).map((k) => caches.delete(k)));
    await self.clients.claim();
    // OCR files (≈7 MB) are fetched in the background so the first load stays light.
    caches.open(SHELL).then((c) => c.addAll(LAZY)).catch(() => {});
  })());
});

async function trimTiles() {
  const cache = await caches.open(TILES);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - MAX_TILES; i++) await cache.delete(keys[i]);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  // OpenStreetMap tiles: cache every tile viewed, serve from cache first.
  if (url.hostname === 'tile.openstreetmap.org') {
    event.respondWith((async () => {
      const cache = await caches.open(TILES);
      const hit = await cache.match(req.url);
      if (hit) return hit;
      try {
        const res = await fetch(req.url, { mode: 'cors' });
        if (res.ok) { cache.put(req.url, res.clone()); trimTiles(); }
        return res;
      } catch {
        return new Response('', { status: 504 });
      }
    })());
    return;
  }

  if (url.origin !== self.location.origin) return; // Nominatim etc.: network only

  // Page navigations: cached one-page app shell first, then network, else the offline page.
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      const hit = (await caches.match('./index.html')) || (await caches.match('./'));
      if (hit) return hit;
      try {
        return await fetch(req);
      } catch {
        return (await caches.match('./offline.html')) || new Response('offline', { status: 503 });
      }
    })());
    return;
  }

  // Shell files: cache first, then network (and keep a copy).
  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok) (await caches.open(SHELL)).put(req, res.clone());
      return res;
    } catch {
      return new Response('', { status: 504 });
    }
  })());
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(self.clients.matchAll({ type: 'window' }).then((list) => (list[0] ? list[0].focus() : self.clients.openWindow('./'))));
});
